#include <iostream>
#include <memory>
#include <stdexcept>
class IntBuffer {
public:
    explicit IntBuffer(std::size_t n) : data_(std::make_unique<int[]>(n)), size_(n) {}
    int& at(std::size_t i) { if (i >= size_) throw std::out_of_range("index"); return data_[i]; }
    std::size_t size() const { return size_; }
private: std::unique_ptr<int[]> data_; std::size_t size_;
};
int main() { IntBuffer values{2}; values.at(0)=6; values.at(1)=7; std::cout << values.at(0)+values.at(1) << '\n'; }
